export const instant = false // with cacheComponents: block instead of streaming a shell

export default async function Page({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params
  const item = await db.item.findUnique({ where: { id } })
  if (!item) notFound() // runs before any Suspense boundary, so the status is a real 404
  return <Item item={item} />
}
